const INDEX = new Map(Object.entries(IMMERSIVE_LAYOUT_MATERIAL_ZONES).map(([layoutId, records]) => [layoutId, new Map(records.map((record) => [`${record.nodeIndex}/${record.meshIndex}/${record.primitiveIndex}`, record]))]));

export function getImmersiveMaterialZone(layoutId, nodeIndex, meshIndex, primitiveIndex) {
  return INDEX.get(layoutId)?.get(`${nodeIndex}/${meshIndex}/${primitiveIndex}`) || null;
}
